/**
 * The network fixture, proven: a non-loopback request is refused and FAILS its test, a
 * loopback one goes through, and a test that owns its stub still wins.
 *
 * "Without the fixture, the same test reaches the network" is proven outside this run, by
 * `yarn test:fixtures:prove`, which fetches an address from the RFC 5737 documentation
 * range -- unroutable by definition, so nothing is ever contacted -- with and without
 * `test/testsetup-network.ts`, and requires a socket connect in one run and none in the other.
 */
import * as http from 'node:http';
import * as https from 'node:https';
import type { AddressInfo } from 'node:net';

import type * as RcapiNS from '../src/core/rcapi';

const GUARD = Symbol.for('houston.test.network-guard');

/** What this test itself caused, taken out so the setup file's verdict does not fire. */
function drained(): string[] {
  const holder = globalThis as unknown as Record<symbol, { reaches: string[] } | undefined>;
  return holder[GUARD]?.reaches.splice(0) ?? [];
}

describe('a request that would leave the machine', () => {
  it('is refused with the shape a name that does not resolve has', async () => {
    const reached = fetch('https://releases.rocket.chat/8.5.1/info');
    await expect(reached).rejects.toMatchObject({
      name: 'TypeError',
      message: 'fetch failed',
      cause: { code: 'ENOTFOUND', message: expect.stringContaining('does not reach the network') },
    });
    expect(drained()).toEqual(['GET https://releases.rocket.chat/8.5.1/info']);
  });

  it('is reported by the seam as a transport failure, the path an offline box takes', async () => {
    const rcapi = require('../src/core/rcapi') as typeof RcapiNS;
    expect(await rcapi.releasesReachable()).toBeNull();
    expect(drained()).toEqual(['GET https://releases.rocket.chat/8.5.1/info']);
  });

  it('names the method and the URL, for a request object as well as a string', async () => {
    await expect(fetch(new Request('https://203.0.113.10/x', { method: 'POST' }))).rejects.toThrow(
      'fetch failed',
    );
    await expect(fetch(new URL('http://example.invalid/'))).rejects.toThrow('fetch failed');
    expect(drained()).toEqual(['POST https://203.0.113.10/x', 'GET http://example.invalid/']);
  });
});

/** The error a client request ends with, or null for an answer. */
function outcome(request: http.ClientRequest): Promise<NodeJS.ErrnoException | null> {
  return new Promise((resolve) => {
    request.on('response', (response: http.IncomingMessage) => {
      response.resume();
      resolve(null);
    });
    request.on('error', resolve);
  });
}

describe('a request through node:http or node:https that would leave the machine', () => {
  // The seam sends every hop through node's own client now, not fetch, so a
  // guard on the fetch global alone saw none of its requests: `releasesReachable` above
  // would have dialled releases.rocket.chat.
  it('is refused with the shape node gives a name that does not resolve', async () => {
    const request = https.request({ hostname: 'releases.rocket.chat', path: '/8.5.1/info' });
    request.end();
    expect(await outcome(request)).toMatchObject({
      code: 'ENOTFOUND',
      syscall: 'getaddrinfo',
      message: expect.stringContaining('does not reach the network'),
    });
    expect(drained()).toEqual(['GET https://releases.rocket.chat/8.5.1/info']);
  });

  it('names the method and the URL, for every way of calling it', async () => {
    const refused = [
      http.request('http://203.0.113.10/x?q=1', { method: 'post' }),
      http.get(new URL('http://example.invalid:8080/')),
      https.get('https://[2001:db8::1]:8443/y'),
      http.request({ host: '198.51.100.7', port: 3000, path: '/api/info', method: 'HEAD' }),
    ];
    // Listened to at once: the refusal is emitted on the next tick, as a failed lookup is.
    const outcomes = refused.map(outcome);
    for (const request of refused) request.end();
    for (const ended of outcomes) expect(await ended).toMatchObject({ code: 'ENOTFOUND' });
    expect(drained()).toEqual([
      'POST http://203.0.113.10/x?q=1',
      'GET http://example.invalid:8080/',
      'GET https://[2001:db8::1]:8443/y',
      'HEAD http://198.51.100.7:3000/api/info',
    ]);
  });
});

describe('loopback is not the network', () => {
  let server: http.Server;
  let base = '';
  beforeAll(async () => {
    server = http.createServer((_request, response) => response.end('here'));
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
    base = `http://127.0.0.1:${String((server.address() as AddressInfo).port)}`;
  });
  afterAll(async () => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  });

  it('reaches a server this process started', async () => {
    const response = await fetch(`${base}/`);
    expect(await response.text()).toBe('here');
    expect(drained()).toEqual([]);
  });

  it('reaches it through node:http as well, by every loopback name', async () => {
    const port = base.split(':')[2] as string;
    for (const host of ['127.0.0.1', 'localhost']) {
      const body = await new Promise<string>((resolve, reject) => {
        http
          .get(`http://${host}:${port}/`, (response) => {
            let text = '';
            response.on('data', (chunk: Buffer) => (text += chunk.toString('utf8')));
            response.on('end', () => resolve(text));
          })
          .on('error', reject);
      });
      expect(body).toBe('here');
    }
    expect(drained()).toEqual([]);
  });
});

describe('a test that owns a stub still wins', () => {
  afterEach(() => {
    jest.dontMock('../src/core/rcapi');
    jest.resetModules();
  });

  it('by stating the answer at the function above the seam', async () => {
    jest.resetModules();
    jest.doMock('../src/core/rcapi', () => ({
      ...jest.requireActual<typeof RcapiNS>('../src/core/rcapi'),
      releasesReachable: async () => 200,
    }));
    const rcapi = require('../src/core/rcapi') as typeof RcapiNS;
    expect(await rcapi.releasesReachable()).toBe(200);
    expect(drained()).toEqual([]);
  });

  it('by replacing fetch itself for the length of the test', async () => {
    const guarded = globalThis.fetch;
    globalThis.fetch = (async () => new Response('stubbed', { status: 200 })) as typeof fetch;
    try {
      const response = await fetch('https://releases.rocket.chat/8.5.1/info');
      expect(await response.text()).toBe('stubbed');
    } finally {
      globalThis.fetch = guarded;
    }
    expect(drained()).toEqual([]);
  });
});

/**
 * The engine fixture, proven: the preflight passes with no daemon reached, and a test that
 * wants the engine DOWN -- or wants the real functions -- still gets its way.
 *
 * "Without the fixture, the same test reaches Docker" is proven outside this run, by
 * `yarn test:fixtures:prove`, which drives the same preflight with and without
 * `test/testsetup-engine.ts` and a recording stand-in for `docker` on PATH.
 */
import * as host from '../src/core/runner/host';
import * as policy from './testsetup-policy';

import type * as HostNS from '../src/core/runner/host';
import type * as PreconditionsNS from '../src/core/lifecycle/preconditions';

describe('the engine answers healthy, whatever this machine has', () => {
  it('says the daemon is up and the compose plugin is 2.29.0', async () => {
    expect(await host.dockerAvailable()).toBe(true);
    expect(await host.dockerAvailable({ maxAgeMs: 0 })).toBe(true);
    expect(await host.composeVersion()).toBe('2.29.0');
  });

  it('answers WITHOUT asking: the real probe would have said no', async () => {
    // `docker` is absent at the process seam (test/testsetup-cloud.ts), so the real
    // `dockerAvailable` -- which runs `docker info` -- can only answer false here. `true`
    // above therefore came from the fixture, not from a daemon.
    const real = jest.requireActual<typeof HostNS>('../src/core/runner/host');
    expect(await real.dockerAvailable({ maxAgeMs: 0 })).toBe(false);
    expect(await real.composeVersion()).toBeNull();
    expect(policy.record()).toEqual([]);
  });

  it('lets the real preflight pass, which is what twenty-two tests of earlier releases needed', async () => {
    const preconditions = require('../src/core/lifecycle/preconditions') as typeof PreconditionsNS;
    await expect(preconditions.requireDocker()).resolves.toBeUndefined();
  });

  it('leaves the rest of runner/host real', async () => {
    // Only the two probes earlier releases' fixture replaced are replaced. Anything else answering
    // from a fixture would be a fixture hiding what a test asserts.
    const real = jest.requireActual<typeof HostNS>('../src/core/runner/host');
    expect(host.hostMemory).toBe(real.hostMemory);
    expect(host.dockerCapacity).toBe(real.dockerCapacity);
    expect(await host.dockerCapacity()).toBeNull();
  });
});

describe('a test that owns a stub still wins', () => {
  afterEach(() => {
    // Put the suite's engine back rather than `dontMock` it -- see testsetup-cloud.test.ts.
    jest.doMock('../src/core/runner/host', () => policy.healthyHost());
    jest.resetModules();
  });

  it('can say the engine is DOWN, and the preflight then refuses', async () => {
    jest.resetModules();
    jest.doMock('../src/core/runner/host', () => ({
      ...jest.requireActual<typeof HostNS>('../src/core/runner/host'),
      dockerAvailable: async () => false,
    }));
    const preconditions = require('../src/core/lifecycle/preconditions') as typeof PreconditionsNS;
    await expect(preconditions.requireDocker()).rejects.toThrow("Docker isn't running");
  });

  it('can say the compose plugin is too old, and the preflight then refuses', async () => {
    jest.resetModules();
    // BOTH answers, because a test that registers its own `runner/host` owns the whole
    // module: spreading the actual one puts the REAL `dockerAvailable` back, which finds no
    // docker and refuses for the wrong reason.
    jest.doMock('../src/core/runner/host', () => ({
      ...jest.requireActual<typeof HostNS>('../src/core/runner/host'),
      dockerAvailable: async () => true,
      composeVersion: async () => '1.29.2',
    }));
    const preconditions = require('../src/core/lifecycle/preconditions') as typeof PreconditionsNS;
    await expect(preconditions.requireDocker()).rejects.toThrow('1.29.2');
  });
});

/**
 * Infrastructure tooling is ABSENT unless a test owns a stub above the seam.
 *
 * It covers all six tools. Its reasoning is kept here rather than summarised, because both
 * halves of it are counter-intuitive and both were paid for:
 *
 * **A guard rail, not a convenience.** `eksctl create cluster` builds real infrastructure
 * and bills for it. A test that stubs the seam that USED to be right is indistinguishable
 * from one that stubs the right seam until something has been created: `create_cluster`
 * moved to a streaming runner, a test still stubbing the old seam stopped intercepting,
 * and it shelled out to REAL `eksctl` against REAL credentials. It failed for want of a
 * config, which is not a safety property.
 *
 * **ABSENT, not merely blocked, and the verb is what is refused.** `k8s.exec.run` never
 * throws -- a launch failure becomes `returncode: 127` -- so a guard that raised on a
 * read-only call escaped that catch and broke fifteen tests that were only asking a
 * question, then a sixteenth. A question therefore gets the answer every caller already
 * handles: the tool is not installed. Only `create` and `delete` are refused.
 *
 * ## Measured on this tree before it existed
 *
 * One ordinary `yarn test` executed the real tools FORTY-FIVE times: `aws sts
 * get-caller-identity` against this box's credentials, `aws configure get region`, `kubectl
 * config get-contexts` reading the real `~/.kube/config`, `kubectl --context ... get --raw
 * /readyz`, `eksctl version`, and a dozen `docker` queries against the running daemon. None
 * was a spend -- but ten tests failed on a PATH without the tools, so the suite's answer
 * depended on what this machine has installed, exactly as earlier releases' suite once did.
 *
 * ## Three layers, because each one alone has a hole that was measured
 *
 * 1. **`seams/exec`** -- where a process is launched. A question gets `127`; a spend is
 *    refused.
 * 2. **`core/kube/tools`** -- where PRESENCE is decided. `which()` is a PATH lookup that
 *    never reaches the process seam, and it decides presence for twenty call sites.
 * 3. **`node:child_process`, underneath both** -- a backstop the module registry cannot
 *    remove. `jest.dontMock` marks a module id "never mock" and `jest.resetModules()` does
 *    not clear that, so a test that swaps the exec seam for a scenario and then `dontMock`s
 *    it runs the rest of its file on the UNGUARDED real seam; `kube-behaviour.test.ts` did
 *    exactly that. Here, a real tool that reaches `child_process` runs a stand-in that
 *    prints the same "unavailable" line and exits 127 -- and the test FAILS, by name.
 *
 * A refusal is also RECORDED, and the test that made it fails in `afterEach`, because both
 * process seams above this one catch everything (see `testsetup-policy.ts`): a thrown
 * refusal would otherwise arrive as an ordinary failed build and be tolerated.
 *
 * ## A test that owns a stub still wins, structurally
 *
 * A test that means to exercise a cloud path stubs `seams/kubectl`, `core/kube/exec`,
 * `seams/aws-cli`, `seams/docker-cli` or the function above them; all of those sit ABOVE the
 * process seam, so the test never reaches the guard at all. A test that needs a tool PRESENT
 * registers its own `jest.mock` of `core/kube/tools`, which is registered after this file runs and
 * replaces this one. A test proving the seam itself runs a scripted stand-in it built under the
 * temp root, which the policy lets through by construction.
 *
 * NOT COVERED, and recorded rather than implied: a GRANDCHILD. Another program a test runs
 * -- a shell script, a second node -- is a separate process, and whatever it launches never
 * passes through this one. `child_process.exec`/`execSync` take a shell string and are not
 * wrapped; no test or production module uses them for any of the six.
 */
import type * as ChildProcessNS from 'node:child_process';

import type * as PolicyNS from './testsetup-policy';

jest.mock('../src/seams/exec', () =>
  (require('./testsetup-policy') as typeof PolicyNS).guardedExec(),
);
jest.mock('../src/core/kube/tools', () =>
  (require('./testsetup-policy') as typeof PolicyNS).guardedTools(),
);

const policy = require('./testsetup-policy') as typeof PolicyNS;
// Before any test can prepend a directory of its own fakes -- see `testOwned`.
policy.rememberAmbientPath();

// --- the backstop -------------------------------------------------------------------

interface Backstop {
  /** Re-pointed by every test file, because the module object outlives each of them. */
  note: (text: string) => void;
}
type Launcher = (...args: unknown[]) => unknown;
type PatchedModule = Record<string, Launcher> & Record<symbol, Backstop | undefined>;

const BACKSTOP = Symbol.for('houston.test.cloud-backstop');
// THE REAL MODULE OBJECT, not an import-interop copy of it: `seams/exec` reads
// `spawn` from this object at every call, and a patch on a copy would reach nothing.
const childProcess = require('node:child_process') as typeof ChildProcessNS & PatchedModule;

if (childProcess[BACKSTOP] === undefined) {
  const state: Backstop = { note: () => undefined };
  childProcess[BACKSTOP] = state;

  /** `node -e RELAY -- <file> <args...>` is how `seams/exec` merges stderr; see through it. */
  const unwrap = (file: string, args: readonly string[]): readonly string[] =>
    file === process.execPath && args[0] === '-e' && args[2] === '--'
      ? args.slice(3)
      : [file, ...args];

  const optionsOf = (rest: readonly unknown[]): { env?: NodeJS.ProcessEnv } | undefined =>
    rest.find(
      (one): one is { env?: NodeJS.ProcessEnv } =>
        typeof one === 'object' && one !== null && !Array.isArray(one),
    );

  const intercept = (name: string, real: Launcher): Launcher =>
    function backstop(this: unknown, ...call: unknown[]): unknown {
      const file = String(call[0]);
      const hasArgs = Array.isArray(call[1]);
      const args = hasArgs ? (call[1] as unknown[]).map(String) : [];
      const rest = call.slice(hasArgs ? 2 : 1);
      const argv = unwrap(file, args);
      const verdict = policy.launchVerdict(argv, optionsOf(rest)?.env);
      if (verdict === 'launch') return real.apply(this, call);
      const tool = policy.toolOf(argv);
      state.note(
        verdict === 'refuse'
          ? policy.refusalText(tool, argv, 'run')
          : `\`${argv.slice(0, 4).join(' ')}\` reached child_process.${name}, BELOW the ` +
              'process seam -- the module guard that should have answered it was removed ' +
              '(jest.dontMock/unmock) or bypassed. A stand-in ran instead of the real tool.',
      );
      const standIn = [
        '-e',
        `process.stderr.write(${JSON.stringify(policy.unavailable(tool))});process.exit(127)`,
      ];
      return real.apply(this, [process.execPath, standIn, ...rest]);
    };

  for (const name of ['spawn', 'spawnSync', 'execFile', 'execFileSync']) {
    const real = childProcess[name];
    if (real !== undefined) childProcess[name] = intercept(name, real);
  }
}

(childProcess[BACKSTOP] as Backstop).note = (text: string) => {
  policy.record().push(text);
};

afterEach(() => {
  policy.verdict('this test');
});
afterAll(() => {
  policy.verdict('a hook in this file');
});

/**
 * The cloud guard, proven: it answers ABSENT, refuses a spend loudly, cannot be removed
 * through the module registry, and still loses to a test that owns its stub.
 *
 * The first three cases, per tool, are the guard's own three claims. The rest cover what
 * measurement showed also mattered: presence answered from the box, a refusal swallowed by the
 * seam above, and a guard stripped by `jest.dontMock`.
 *
 * "Without the fixture, the same test reaches them" is a claim about a run WITHOUT this
 * file's setup, which no test inside that run can make. `yarn test:fixtures:prove` makes it:
 * it runs planted specs with and without each setup file, with a recording stand-in on
 * PATH, and requires the reach to appear in one and not the other.
 */
import * as childProcess from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { kube } from '../src/core/kube/exec';
import * as tools from '../src/core/kube/tools';
import { capture, inherit, startDetached, stream } from '../src/seams/exec';
import * as policy from './testsetup-policy';

import type * as ToolsNS from '../src/core/kube/tools';

const TOOLS = ['eksctl', 'aws', 'kubectl', 'helm', 'kind', 'docker'] as const;

/** What this test itself caused, taken out so the setup file's verdict does not fire. */
function drained(): string[] {
  return policy.record().splice(0);
}

afterEach(() => {
  drained();
});

describe('the six tools are absent, not merely blocked', () => {
  it.each(TOOLS)('reports %s unavailable, with the reason on stderr', async (tool) => {
    const result = await capture([tool, 'version', 'fixture'], { encoding: 'utf8' });
    expect(result.exitCode).toBe(127);
    expect(result.stdout).toBe('');
    expect(result.stderr).toBe(`${tool} is unavailable in the test suite`);
  });

  it.each(TOOLS)('refuses a %s spend before anything is launched', async (tool) => {
    await expect(capture([tool, 'create', 'fixture'])).rejects.toThrow(
      `the test suite tried to run \`${tool} create fixture\``,
    );
    await expect(stream([tool, 'delete', 'fixture'])).rejects.toThrow(
      `the test suite tried to stream \`${tool} delete fixture\``,
    );
    expect(drained()).toHaveLength(2);
  });

  it.each(TOOLS)('never starts a streaming, inherited or detached %s', async (tool) => {
    const chunks: string[] = [];
    const streamed = await stream([tool, 'version'], {
      encoding: 'utf8',
      onStderr: (chunk) => chunks.push(String(chunk)),
    });
    expect(streamed.exitCode).toBe(127);
    expect(chunks.join('')).toBe(`${tool} is unavailable in the test suite`);
    expect((await inherit([tool, 'version'])).exitCode).toBe(127);
    await expect(startDetached([tool, 'version'])).rejects.toMatchObject({
      name: 'SpawnFailure',
      cause: { code: 'ENOENT' },
    });
  });

  it('carries the reason on stdout when the caller merged the two streams', async () => {
    const merged = await capture(['docker', 'info'], { encoding: 'utf8', mergeStderr: true });
    expect(merged).toMatchObject({
      exitCode: 127,
      stdout: 'docker is unavailable in the test suite',
      stderr: null,
    });
    const bytes = await capture(['docker', 'info']);
    expect(Buffer.isBuffer(bytes.stderr)).toBe(true);
  });

  it('refuses a real tool named by its absolute path, whether or not it exists here', async () => {
    // A de-pointed stub does not always reach for the bare name. The answer must not
    // depend on whether this machine has the binary at that path.
    const result = await capture(['/usr/local/bin/kubectl', 'version'], { encoding: 'utf8' });
    expect(result.exitCode).toBe(127);
    await expect(capture(['/usr/local/bin/eksctl', 'create', 'cluster'])).rejects.toThrow(
      'creates or destroys real infrastructure',
    );
    // Taken out HERE: an undrained refusal fails the test in the setup file's `afterEach`,
    // which runs before this file's -- observed, the first time this case was written.
    expect(drained()).toEqual([expect.stringContaining('eksctl create cluster')]);
  });

  it('lets everything that is not one of the six straight through', async () => {
    const result = await capture([process.execPath, '-e', 'process.stdout.write("real")'], {
      encoding: 'utf8',
    });
    expect(result).toMatchObject({ exitCode: 0, stdout: 'real' });
  });
});

describe('presence is absent too, because it is not decided at the process seam', () => {
  it.each(TOOLS)('reports %s as not installed through which() and tool()', async (tool) => {
    expect(tools.which(tool)).toBe('');
    const found = await tools.tool(tool);
    expect(found.path).toBe('');
    expect(tools.toolPresent(found)).toBe(false);
  });

  it('answers the same for a tool that is not one of the six', () => {
    // `sh` is on every PATH this suite runs on; the guard is about the six and only them.
    expect(tools.which('sh')).not.toBe('');
  });
});

describe('a refusal the seam above swallows is still a failure', () => {
  it('is recorded when seams/kubectl turns it into an ordinary 127', async () => {
    // `seams/kubectl.ts` catches EVERY error from `capture` and returns returncode 127, so
    // a thrown refusal arrives at the caller as a failed command. Earlier releases' kubectl
    // call caught only launch failures, which is why their guard could simply raise.
    const result = await kube.run(['kubectl', 'delete', 'namespace', 'houston-fixture']);
    expect(result.returncode).toBe(127);
    expect(result.stderr).toContain('creates or destroys real infrastructure');
    // ...and the record is what fails the test in `afterEach`, where no catch can reach.
    expect(drained()).toEqual([expect.stringContaining('kubectl delete namespace')]);
  });
});

describe('the backstop below the module registry', () => {
  it('runs a stand-in instead of a real tool that reached child_process directly', () => {
    const result = childProcess.spawnSync('docker', ['info'], { encoding: 'utf8' });
    expect(result.status).toBe(127);
    expect(result.stderr).toBe('docker is unavailable in the test suite');
    expect(drained()).toEqual([expect.stringContaining('BELOW the process seam')]);
  });

  it('sees through the relay seams/exec uses to merge stderr', () => {
    const result = childProcess.spawnSync(
      process.execPath,
      ['-e', 'relay', '--', 'kubectl', 'version'],
      { encoding: 'utf8' },
    );
    expect(result.status).toBe(127);
    expect(drained()).toEqual([expect.stringContaining('`kubectl version`')]);
  });
});

describe('what the test built is the test’s own', () => {
  let scratch = '';
  beforeEach(() => {
    scratch = fs.mkdtempSync(path.join(os.tmpdir(), 'houston-cloud-guard-'));
    fs.writeFileSync(path.join(scratch, 'docker'), '#!/bin/sh\nprintf fake\n', { mode: 0o755 });
  });
  afterEach(() => {
    fs.rmSync(scratch, { recursive: true, force: true });
  });

  it('runs a scripted stand-in named by its absolute path', async () => {
    const result = await capture([path.join(scratch, 'docker'), 'info'], { encoding: 'utf8' });
    expect(result).toMatchObject({ exitCode: 0, stdout: 'fake' });
  });

  it('runs a scripted stand-in found first on a PATH the test handed the launch', async () => {
    const env = { ...process.env, PATH: `${scratch}${path.delimiter}${process.env.PATH ?? ''}` };
    const result = await capture(['docker', 'info'], { encoding: 'utf8', env });
    expect(result).toMatchObject({ exitCode: 0, stdout: 'fake' });
  });

  it('owns what it built under the temp root, and nothing outside it', () => {
    expect(policy.testOwned(path.join(scratch, 'docker'))).toBe(true);
    expect(policy.testOwned('/usr/bin/docker')).toBe(false);
    // A temp directory the ENVIRONMENT had on PATH is not a fake either. MEASURED: with
    // "under the temp root" as the whole rule, a logging shim on PATH under /tmp was taken
    // for a stand-in and let eleven real launches through -- what a CI runner unpacking
    // tools into /tmp/bin would get. That case needs a run whose ambient PATH holds such a
    // directory, so `yarn test:fixtures:prove` makes it: its recording shim lives there.
  });

  it('treats a link to the real binary as the real binary', () => {
    const link = path.join(scratch, 'kubectl');
    fs.symlinkSync('/usr/bin/env', link);
    expect(policy.testOwned(link)).toBe(false);
  });
});

describe('a test that owns a stub still wins', () => {
  afterEach(() => {
    // Put the suite's guard back rather than `dontMock` -- the trap the next block refuses.
    jest.doMock('../src/core/kube/tools', () => policy.guardedTools());
    jest.resetModules();
  });

  it('wins for presence, with its own registration of kube/tools', () => {
    jest.resetModules();
    jest.doMock('../src/core/kube/tools', () => ({
      ...jest.requireActual<typeof ToolsNS>('../src/core/kube/tools'),
      which: (name: string) => `/opt/fixture/${name}`,
    }));
    const owned = require('../src/core/kube/tools') as typeof ToolsNS;
    expect(owned.which('kubectl')).toBe('/opt/fixture/kubectl');
  });

  it('wins for a launch, by stubbing the seam above the process seam', async () => {
    const real = kube.run;
    kube.run = async (argv) => ({ argv: [...argv], returncode: 0, stdout: 'v1.36.3', stderr: '' });
    try {
      expect((await kube.run(['kubectl', 'version', '--client'])).stdout).toBe('v1.36.3');
      expect(drained()).toEqual([]);
    } finally {
      kube.run = real;
    }
  });
});

/**
 * NO TEST MAY STRIP A GUARD THROUGH THE REGISTRY, except by a reviewed, reasoned exception.
 *
 * `jest.dontMock(id)` and `jest.unmock(id)` mark the id "never mock", and
 * `jest.resetModules()` does not clear that -- so a cleanup that `dontMock`s a guarded
 * module leaves every later test in its file on the unguarded real module.
 * `test/core/invariants/kube-behaviour.test.ts` did exactly that to `seams/exec` until this
 * existed. The runtime backstop makes a real LAUNCH loud; this makes the strip itself
 * impossible to land, for presence and the engine as well as for launches.
 */
const REGISTRY_EXCEPTIONS: readonly { file: string; target: string; reason: string }[] = [
  {
    file: 'test/core/runner/host.test.ts',
    target: 'host',
    reason:
      'its subject is composeVersion, which the engine fixture replaces; its docker seam ' +
      'stays its own mock, so nothing reaches a real engine',
  },
];

describe('the module registry cannot take a guard away', () => {
  it('finds no dontMock or unmock of a guarded module outside the reviewed exceptions', () => {
    const root = path.resolve(__dirname, '..');
    const specs: string[] = [];
    const walk = (dir: string): void => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const absolute = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(absolute);
        else if (entry.name.endsWith('.test.ts')) specs.push(absolute);
      }
    };
    walk(__dirname);
    const guarded = new Map(
      Object.entries(policy.GUARDED_MODULES).map(([name, file]) => [file, name]),
    );
    const found: string[] = [];
    for (const spec of specs) {
      const text = fs.readFileSync(spec, 'utf8');
      for (const match of text.matchAll(/jest\.(?:dontMock|unmock)\(\s*['"]([^'"]+)['"]/gu)) {
        const target = guarded.get(`${path.resolve(path.dirname(spec), match[1] ?? '')}.ts`);
        if (target === undefined) continue;
        const relative = path.relative(root, spec).split(path.sep).join('/');
        const allowed = REGISTRY_EXCEPTIONS.some(
          (row) => row.file === relative && row.target === target,
        );
        if (!allowed) found.push(`${relative} strips the ${target} guard with ${match[0]})`);
      }
    }
    expect(found).toEqual([]);
    // The exceptions must still describe the tree, or the list stops meaning anything.
    for (const row of REGISTRY_EXCEPTIONS) {
      expect(fs.existsSync(path.join(root, row.file))).toBe(true);
    }
  });
});

/**
 * The suite does not reach the network, and a test that tries is FAILED, not forgiven.
 *
 * The fourth fixture, and one earlier releases' suite never had: its one real call to
 * `releases.rocket.chat` was cured by a stub of the versions lookup's HTTP get, so the reason
 * for a guard had to be measured again, here.
 *
 * MEASURED, not assumed. The whole Jest suite was run with every name lookup, socket
 * connect and `fetch` to a non-loopback address recorded. It passes 1904/1904 with no
 * network at all -- and it still made ONE real reach: `test/core/doctor.test.ts` runs the
 * doctor's `versions` check, which asked `https://releases.rocket.chat/8.5.1/info` over the
 * wire. Offline that degrades to "could not reach", which the test tolerates; online it
 * reads a live answer. A test whose path depends on whether the machine is online is one
 * that passes here and fails somewhere else, and nobody sees the difference until then.
 *
 * ## Why the reach FAILS the test instead of merely throwing
 *
 * `seams/rc-http` turns any rejection into `RequestFailed("could not reach ...")`, and every
 * caller already handles that -- which is exactly the problem. A guard that only threw would
 * put every such test on the offline branch and let it pass, so the reach would be HIDDEN
 * rather than REMOVED. So the attempt is refused (nothing leaves the machine; the rejection
 * has the shape undici gives when a name does not resolve), recorded, and the test that made
 * it fails in `afterEach` with the URL named. The cure is the test owning its stub.
 *
 * Loopback is not the network: the web layer's integration tests and `seams/rc-http`'s own
 * contract tests talk to a server this process started on 127.0.0.1, and they pass through.
 *
 * ## `node:http` and `node:https` too, because the seam speaks through them
 *
 * `seams/rc-http` sends every hop through node's own client now, not fetch -- fetch adds
 * headers requests never sends and cannot be told not to -- so a guard on the
 * `fetch` global alone would see none of the seam's requests. `request` and `get` of both
 * modules are wrapped, on the REAL module objects, which outlive each test file as
 * `child_process` does in `testsetup-cloud.ts`: installed once per worker, the recorder
 * re-pointed by every file. A refused request is a real `ClientRequest` whose connection is
 * never opened -- its `createConnection` throws -- so it fails with the shape node gives a
 * name that does not resolve, and nothing is dialled, an IP literal included.
 *
 * NOT GUARDED, and recorded rather than implied: `node:tls`, `node:net` and raw sockets.
 * Only `seams/rc-http.ts` may call `fetch` (an eslint `no-restricted-globals` rule), and the
 * same measurement found no socket-level reach outside it. `tls.verify` dials whatever host
 * it is given; every test of it dials loopback.
 */
import type * as HttpNS from 'node:http';

const GUARD = Symbol.for('houston.test.network-guard');

interface NetworkGuard {
  /** Every refused reach since the last check, as `METHOD url`. */
  readonly reaches: string[];
}

function loopback(host: string): boolean {
  const bare = host.startsWith('[') && host.endsWith(']') ? host.slice(1, -1) : host;
  return bare === 'localhost' || bare === '::1' || /^127\.\d+\.\d+\.\d+$/u.test(bare);
}

function requestOf(input: unknown, init: RequestInit | undefined): { url: string; method: string } {
  if (typeof input === 'string') return { url: input, method: init?.method ?? 'GET' };
  if (input instanceof URL) return { url: input.href, method: init?.method ?? 'GET' };
  const request = input as { url?: string; method?: string };
  return { url: String(request.url ?? input), method: init?.method ?? request.method ?? 'GET' };
}

const holder = globalThis as unknown as Record<symbol, NetworkGuard | undefined>;
if (holder[GUARD] === undefined) {
  const guard: NetworkGuard = { reaches: [] };
  holder[GUARD] = guard;
  const realFetch = globalThis.fetch;

  globalThis.fetch = function guardedFetch(
    input: Parameters<typeof fetch>[0],
    init?: Parameters<typeof fetch>[1],
  ): Promise<Response> {
    const { url, method } = requestOf(input, init);
    let parsed: URL | undefined;
    try {
      parsed = new URL(url);
    } catch {
      parsed = undefined;
    }
    const network = parsed !== undefined && /^(https?|wss?):$/u.test(parsed.protocol);
    if (!network || loopback(parsed?.hostname ?? '')) return realFetch(input, init);

    guard.reaches.push(`${method.toUpperCase()} ${url}`);
    // The shape undici rejects with when a name does not resolve, so the code under test
    // takes the path a genuinely offline machine takes -- and the test still fails below.
    const cause = Object.assign(
      new Error(
        `getaddrinfo ENOTFOUND ${parsed?.hostname ?? url} (refused: the test suite does not ` +
          'reach the network)',
      ),
      { code: 'ENOTFOUND', errno: -3008, syscall: 'getaddrinfo', hostname: parsed?.hostname },
    );
    return Promise.reject(new TypeError('fetch failed', { cause }));
  } as typeof fetch;

  const verdict = (when: string): void => {
    if (guard.reaches.length === 0) return;
    const named = guard.reaches.splice(0);
    throw new Error(
      `${when} reached the network: ${named.join(', ')}. Nothing left the machine -- the ` +
        'request was refused -- but a test whose answer depends on whether this box is ' +
        'online passes here and fails on a runner. Stub src/seams/rc-http.ts, or the ' +
        'core/rcapi.ts function above it, in the test that owns the call.',
    );
  };
  afterEach(() => {
    verdict('this test');
  });
  afterAll(() => {
    verdict('a hook in this file');
  });
}

// --- node:http and node:https -----------------------------------------------------------

interface ClientBackstop {
  /** Re-pointed by every test file, because the module object outlives each of them. */
  note: (reach: string) => void;
}
type Requester = (...call: unknown[]) => HttpNS.ClientRequest;
type ClientModule = Record<'request' | 'get', Requester> &
  Record<symbol, ClientBackstop | undefined>;

const CLIENT_BACKSTOP = Symbol.for('houston.test.network-client-backstop');

/** `request(options[, cb])` or `request(url[, options][, cb])`: where it would go, and how. */
function destinationOf(
  scheme: string,
  call: readonly unknown[],
): { url: string; method: string; host: string } | null {
  const [first, second] = call;
  let url: URL | undefined;
  let options: Record<string, unknown> = {};
  if (typeof first === 'string' || first instanceof URL) {
    try {
      url = new URL(String(first));
    } catch {
      return null;
    }
    if (typeof second === 'object' && second !== null) options = second as Record<string, unknown>;
  } else if (typeof first === 'object' && first !== null) {
    options = first as Record<string, unknown>;
  }
  if (options.socketPath !== undefined) return null;
  const bare = (value: unknown) => String(value).replace(/^\[(.*)\]$/u, '$1');
  const host = bare(options.hostname ?? options.host ?? url?.hostname ?? 'localhost');
  const port = String(options.port ?? url?.port ?? '');
  const protocol = String(options.protocol ?? url?.protocol ?? scheme);
  const shown = host.includes(':') ? `[${host}]` : host;
  const where = String(options.path ?? (url === undefined ? '/' : `${url.pathname}${url.search}`));
  return {
    url: `${protocol}//${shown}${port === '' ? '' : `:${port}`}${where}`,
    method: String(options.method ?? 'GET').toUpperCase(),
    host,
  };
}

/** The same call, its connection replaced by one that fails before anything is dialled. */
function refusedCall(call: readonly unknown[], refusal: Error): unknown[] {
  const never = {
    agent: undefined,
    createConnection: () => {
      throw refusal;
    },
  };
  const [first, second, ...rest] = call;
  if (typeof first === 'string' || first instanceof URL) {
    if (typeof second === 'object' && second !== null)
      return [first, { ...(second as object), ...never }, ...rest];
    return [first, never, ...(second === undefined ? [] : [second]), ...rest];
  }
  return [{ ...(first as object), ...never }, ...call.slice(1)];
}

for (const [id, scheme] of [
  ['node:http', 'http:'],
  ['node:https', 'https:'],
] as const) {
  // THE REAL MODULE OBJECT, not an import-interop copy of it: `seams/rc-http` reads
  // `request` from this object at every call, and a patch on a copy would reach nothing.
  const client = require(id) as ClientModule;
  if (client[CLIENT_BACKSTOP] === undefined) {
    const state: ClientBackstop = { note: () => undefined };
    client[CLIENT_BACKSTOP] = state;
    const intercept = (real: Requester): Requester =>
      function guardedRequest(this: unknown, ...call: unknown[]): HttpNS.ClientRequest {
        const where = destinationOf(scheme, call);
        if (where === null || loopback(where.host)) return real.apply(this, call);
        state.note(`${where.method} ${where.url}`);
        // The shape node's client fails with when a name does not resolve, as the fetch
        // guard's is undici's, so the code under test takes the offline path.
        const refusal = Object.assign(
          new Error(
            `getaddrinfo ENOTFOUND ${where.host} (refused: the test suite does not reach the ` +
              'network)',
          ),
          { code: 'ENOTFOUND', errno: -3008, syscall: 'getaddrinfo', hostname: where.host },
        );
        return real.apply(this, refusedCall(call, refusal));
      };
    client.request = intercept(client.request);
    client.get = intercept(client.get);
  }
  (client[CLIENT_BACKSTOP] as ClientBackstop).note = (reach: string) => {
    (holder[GUARD] as NetworkGuard).reaches.push(reach);
  };
}

/**
 * Every test file gets its own `HOUSTON_HOME`, and none of them can reach a real one.
 *
 * Jest runs this before every test file. The rule it
 * enforces is in `CLAUDE.md`: a test that writes into `~/.houston` adds users, creates
 * workspaces or leaves ACME material in somebody's actual state directory, and the
 * failure is invisible until it is somebody else's problem.
 *
 * `setupFilesAfterEnv` runs once per test FILE in its own module registry, so each file gets a
 * distinct directory and files cannot see each other's state. The directory is removed
 * afterwards.
 *
 * The legacy `RC_REPRO_*` names are cleared too. They are read as deprecated aliases, so
 * one left in the ambient environment would silently redirect a test's state and print a
 * deprecation warning into the middle of the run.
 */
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

const home = fs.mkdtempSync(path.join(os.tmpdir(), 'houston-jest-'));

for (const name of Object.keys(process.env)) {
  if (name.startsWith('HOUSTON_') || name.startsWith('RC_REPRO_')) {
    delete process.env[name];
  }
}
// And an SSH session's: the CLI reads them to say how to open a localhost URL from another
// computer, so a run over SSH printed a line a local run did not.
delete process.env.SSH_CONNECTION;
delete process.env.SSH_CLIENT;
process.env.HOUSTON_HOME = home;

afterAll(() => {
  fs.rmSync(home, { recursive: true, force: true });
});

/**
 * What the suite may launch and what it may be told is installed: the rules, alone.
 *
 * `test/testsetup-cloud.ts` and `test/testsetup-engine.ts` install these; this file holds
 * only the decisions, for three reasons. A module factory may not close over anything in
 * the file that declares it, so a factory loads its rules from here. A test that took a
 * guarded module out of the registry for a scenario of its own must PUT THE GUARD BACK
 * rather than `jest.dontMock` it, and it does that with the same factory from here. And
 * `testsetup-cloud.test.ts` reads the table the guard enforces rather than a copy of it.
 */
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import type * as HostNS from '../src/core/runner/host';
import type * as ToolsNS from '../src/core/kube/tools';
import type * as ExecNS from '../src/seams/exec';

/** Every external tool the suite must treat as unreachable unless a test owns a stub. */
export const CLOUD_TOOLS: readonly string[] = Object.freeze([
  'eksctl',
  'aws',
  'kubectl',
  'helm',
  'kind',
  'docker',
]);

/**
 * The VERBS that build or destroy, which is the distinction that matters.
 *
 * `eksctl version` is a version probe and `aws sts get-caller-identity` is a question; an
 * ordinary `doctor` asks both and neither costs anything. Refusing the BINARY rather than
 * the verb broke `doctor` outright in earlier releases, because the tool probe it runs at
 * startup was caught in the same net as `eksctl create cluster`.
 */
export const SPEND_VERBS: readonly string[] = Object.freeze(['create', 'delete']);

/** Where a test that means to exercise one of these paths should stub instead. */
export const STUB_POINT: Readonly<Record<string, string>> = Object.freeze({
  eksctl: 'src/seams/aws-cli.ts (awsCli.run / awsCli.stream) or the core/eks.ts caller',
  aws: 'src/seams/aws-cli.ts (awsCli.run / awsCli.stream) or the core/eks.ts caller',
  kubectl: 'src/core/kube/exec.ts (kube.run) or src/seams/kubectl.ts',
  helm: 'src/core/kube/exec.ts (kube.run) or src/seams/kubectl.ts',
  kind: 'src/core/kube/exec.ts (kube.run) or src/seams/kubectl.ts',
  docker: 'src/seams/docker-cli.ts or the core/runner function that calls it',
});

/**
 * The modules the setup files replace, by absolute path. `testsetup-cloud.test.ts` refuses
 * any test that `jest.dontMock`s or `jest.unmock`s one of these outside `REGISTRY_EXCEPTIONS`,
 * because `dontMock` marks the id "never mock" and `jest.resetModules()` does not clear
 * that -- so the guard would stay off for the rest of the file, silently.
 */
export const GUARDED_MODULES: Readonly<Record<string, string>> = Object.freeze({
  exec: path.join(__dirname, '..', 'src', 'seams', 'exec.ts'),
  tools: path.join(__dirname, '..', 'src', 'core', 'kube', 'tools.ts'),
  host: path.join(__dirname, '..', 'src', 'core', 'runner', 'host.ts'),
});

export type LaunchVerdict = 'launch' | 'absent' | 'refuse';

export function isCloudTool(name: string): boolean {
  return CLOUD_TOOLS.includes(name);
}

/** The tool an argv names, by basename, or '' for anything that is not one of the six. */
export function toolOf(argv: readonly string[]): string {
  const name = path.basename(String(argv[0] ?? ''));
  return isCloudTool(name) ? name : '';
}

function realOrResolved(candidate: string): string {
  try {
    return fs.realpathSync(candidate);
  } catch {
    return path.resolve(candidate);
  }
}

const TEMP_ROOT = realOrResolved(os.tmpdir());

/**
 * The PATH directories this file started with, captured ONCE per test file.
 *
 * On the sandbox global rather than in module state, because a test that calls
 * `jest.resetModules()` re-evaluates this module -- often after it has prepended a
 * directory of its own fakes to PATH, which would then be mistaken for the environment's.
 */
const AMBIENT = Symbol.for('houston.test.ambient-path');

function ambientDirectories(): ReadonlySet<string> {
  const holder = globalThis as unknown as Record<symbol, ReadonlySet<string> | undefined>;
  holder[AMBIENT] ??= new Set(
    (process.env.PATH ?? '')
      .split(path.delimiter)
      .filter((one) => one !== '')
      .map(realOrResolved),
  );
  return holder[AMBIENT];
}

/**
 * Whether a path is something a TEST built: under the temp root, and not in a directory the
 * environment already had on PATH.
 *
 * Resolved through symlinks first, so a temp directory holding a link to `/usr/bin/docker`
 * is the real docker and not a fake. Houston itself never installs a binary anywhere, so a
 * runnable `kubectl` under the temp root is either a test's scripted stand-in or a real
 * tool the ENVIRONMENT put there -- a CI runner that unpacks tools into `/tmp/bin` and adds
 * it to PATH. Only the first is a test owning its world, and the difference is exactly
 * which one was on PATH before the test ran: a test prepends its own fakes. MEASURED: with
 * the temp root alone as the rule, a logging shim placed on PATH under `/tmp` was taken for
 * a fake and let eleven real launches through.
 */
export function testOwned(candidate: string): boolean {
  const real = realOrResolved(candidate);
  const underTemp = real === TEMP_ROOT || real.startsWith(`${TEMP_ROOT}${path.sep}`);
  if (!underTemp) return false;
  const ambient = ambientDirectories();
  return !ambient.has(real) && !ambient.has(path.dirname(real));
}

/** Captures the ambient PATH now, before any test in the file can prepend to it. */
export function rememberAmbientPath(): void {
  ambientDirectories();
}

function firstOnPath(name: string, searchPath: string): string {
  for (const directory of searchPath.split(path.delimiter)) {
    if (directory === '') continue;
    const candidate = path.join(directory, name);
    try {
      fs.accessSync(candidate, fs.constants.X_OK);
      return candidate;
    } catch {
      /* not here */
    }
  }
  return '';
}

/**
 * What happens when the suite asks to launch `argv` under `env`.
 *
 * `launch` for anything that is not one of the six, and for a scripted stand-in the test
 * built itself -- named by an absolute path under the temp root, or found first on a PATH
 * the test handed the launch explicitly. `test/seams/aws-cli.test.ts` and
 * `test/seams/docker-cli.test.ts` prove the seam spawns processes correctly by running such
 * stand-ins, and `yarn test:process-contracts` exists to keep them doing it.
 *
 * Everything else that names one of the six is the REAL tool, and the answer does not
 * depend on whether this machine has it installed: a launch with no environment of its own
 * inherits the ambient PATH, which is this box's, so it is guarded without looking. That is
 * the property the fixture exists for -- the same answer here, on a box without Docker, and
 * on a CI runner.
 */
export function launchVerdict(
  argv: readonly string[],
  env: NodeJS.ProcessEnv | undefined,
): LaunchVerdict {
  const name = toolOf(argv);
  if (name === '') return 'launch';
  const file = String(argv[0]);
  if (file.includes('/')) {
    if (testOwned(file)) return 'launch';
  } else if (env !== undefined && typeof env.PATH === 'string') {
    const directories = env.PATH.split(path.delimiter).filter((one) => one !== '');
    // A PATH made ENTIRELY of directories the test created is a world the test built,
    // including the one where the tool is simply not there: `seams/docker-cli.test.ts`
    // asks what happens when no docker exists at all, and the honest answer is ENOENT.
    if (directories.length > 0 && directories.every(testOwned)) return 'launch';
    const found = firstOnPath(name, env.PATH);
    if (found !== '' && testOwned(found)) return 'launch';
  }
  return argv.slice(1).some((word) => SPEND_VERBS.includes(String(word))) ? 'refuse' : 'absent';
}

/**
 * What `which(name)` may answer: a stand-in the test built, or nothing.
 *
 * `core/kube/tools.which` is a PATH lookup that never goes near the process seam, and it
 * decides presence for twenty call sites -- `eks`, `cluster`, `context`, `endpoints`,
 * `reachability`, `preconditions`. Guarding only the launch left presence answering from
 * this machine, so eight `core/eks.test.ts` cases passed only where `aws` is installed.
 */
export function presenceVerdict(name: string, found: string): string {
  if (!isCloudTool(name)) return found;
  return found !== '' && testOwned(found) ? found : '';
}

export function unavailable(name: string): string {
  return `${name} is unavailable in the test suite`;
}

export function refusalText(name: string, argv: readonly string[], action: string): string {
  return (
    `the test suite tried to ${action} \`${name} ${argv.slice(1, 4).join(' ')}\`, which ` +
    `creates or destroys real infrastructure and bills for it. Stub ` +
    `${STUB_POINT[name] ?? 'the adapter above the process seam'} rather than the process ` +
    `seam underneath.`
  );
}

// --- the per-file record --------------------------------------------------------------

/**
 * Every refusal and every launch that got below the seam, since the last verdict.
 *
 * A RECORD, and not only an exception, because both process seams above this one catch
 * everything: `seams/kubectl.ts` turns ANY error from `capture` into `returncode: 127`
 * (earlier releases' kubectl call caught only launch failures, which is why their guard
 * could raise) and `seams/aws-cli.ts` does the same for `awsCli.run` and `awsCli.stream`. A
 * refused `eksctl create cluster` would therefore arrive at the code under test as an
 * ordinary failed build, and a test that tolerates a failed build would pass. So the
 * refusal is thrown -- nothing proceeds -- AND recorded, and the setup file fails the test
 * that made it in `afterEach`, where no catch in production can reach.
 */
const RECORD = Symbol.for('houston.test.cloud-record');

export function record(): string[] {
  const holder = globalThis as unknown as Record<symbol, string[] | undefined>;
  holder[RECORD] ??= [];
  return holder[RECORD];
}

export function verdict(when: string): void {
  const seen = record();
  if (seen.length === 0) return;
  const named = seen.splice(0);
  throw new Error(`${when} reached cloud tooling:\n  - ${named.join('\n  - ')}`);
}

// --- the module factories -----------------------------------------------------------

type Argv = ExecNS.Argv;

/** `null` keeps bytes, exactly as `runMode` reads the option. */
function encodingOf(options: { encoding?: ExecNS.TextEncoding | null }): string | null {
  return 'encoding' in options ? (options.encoding ?? null) : null;
}

function absentResult(argv: Argv): ExecNS.ProcessResult {
  return {
    argv: Object.freeze([...argv]),
    exitCode: 127,
    signal: null,
    stdout: null,
    stderr: null,
  };
}

/**
 * `launch`, `absent`, or the refusal as a REJECTED promise.
 *
 * Rejected rather than thrown: the real launchers never throw synchronously -- a bad argv or
 * timeout comes back as a rejection -- and a caller written against that contract must not
 * see a different shape from the guard than from the seam it replaces.
 */
function decide(
  argv: Argv,
  env: NodeJS.ProcessEnv | undefined,
  action: string,
): 'launch' | 'absent' | Promise<never> {
  const answer = launchVerdict(argv, env);
  if (answer !== 'refuse') return answer;
  const text = refusalText(toolOf(argv), argv, action);
  record().push(text);
  return Promise.reject(new Error(text));
}

/** `seams/exec` with the six tools ABSENT. The factory `testsetup-cloud.ts` registers. */
export function guardedExec(): typeof ExecNS {
  const actual = jest.requireActual<typeof ExecNS>('../src/seams/exec');
  return {
    ...actual,

    capture(argv: Argv, options: ExecNS.CaptureOptions = {}): Promise<ExecNS.ProcessResult> {
      const decision = decide(argv, options.env, 'run');
      if (decision === 'launch') return actual.capture(argv, options);
      if (decision !== 'absent') return decision;
      const text = unavailable(toolOf(argv));
      const as = (value: string): string | Buffer =>
        encodingOf(options) === null ? Buffer.from(value, 'utf8') : value;
      // Merged output lands on stdout and stderr becomes null, which is what `runMode`
      // does with `mergeStderr` -- a docker caller reading one stream must still see why.
      const merged = options.mergeStderr === true;
      return Promise.resolve({
        ...absentResult(argv),
        stdout: merged ? as(text) : as(''),
        stderr: merged ? null : as(text),
      });
    },

    stream(argv: Argv, options: ExecNS.StreamOptions = {}): Promise<ExecNS.ProcessResult> {
      const decision = decide(argv, options.env, 'stream');
      if (decision === 'launch') return actual.stream(argv, options);
      if (decision !== 'absent') return decision;
      const text = unavailable(toolOf(argv));
      const chunk = encodingOf(options) === null ? Buffer.from(text, 'utf8') : text;
      // The reason reaches a streaming caller the way the tool's own stderr would.
      const merged = options.mergeStderr === true;
      (merged ? options.onStdout : options.onStderr)?.(chunk);
      (merged ? options.stdoutSink : options.stderrSink)?.write(chunk);
      return Promise.resolve(absentResult(argv));
    },

    inherit(argv: Argv, options: ExecNS.InheritOptions = {}): Promise<ExecNS.ProcessResult> {
      const decision = decide(argv, options.env, 'run');
      if (decision === 'launch') return actual.inherit(argv, options);
      if (decision !== 'absent') return decision;
      return Promise.resolve(absentResult(argv));
    },

    /**
     * A detached launch has no return code to carry 127, so absence is spelled the way
     * the operating system spells it: the `SpawnFailure`/`ENOENT` a missing binary
     * produces, which `startDetached`'s contract already documents.
     */
    startDetached(
      argv: Argv,
      options: ExecNS.DetachedOptions = {},
    ): Promise<ExecNS.DetachedProcess> {
      const decision = decide(argv, options.env, 'start');
      if (decision === 'launch') return actual.startDetached(argv, options);
      if (decision !== 'absent') return decision;
      const cause = Object.assign(new Error(unavailable(toolOf(argv))), {
        code: 'ENOENT',
        errno: -2,
        syscall: 'spawn',
        path: argv[0],
      });
      return Promise.reject(new actual.SpawnFailure(argv, cause));
    },
  };
}

/** `core/kube/tools` with the six tools NOT INSTALLED, unless a test built a stand-in. */
export function guardedTools(): typeof ToolsNS {
  const actual = jest.requireActual<typeof ToolsNS>('../src/core/kube/tools');
  return {
    ...actual,
    which(name: string): string {
      return presenceVerdict(name, actual.which(name));
    },
    // `tool()` calls `which()` from inside its own module, so replacing the export of one
    // without the other would leave `tool()` answering from this machine.
    async tool(name: string): Promise<ToolsNS.Tool> {
      if (isCloudTool(name) && presenceVerdict(name, actual.which(name)) === '') {
        return actual.makeTool({ name });
      }
      return await actual.tool(name);
    },
  };
}

