  expect(reload).toHaveBeenCalledTimes(1);
});

it('keeps loopback and failed results on the current page', () => {
  const { finish, closed, reload } = gui();
  finish({}, false, { result: { monitoring: true, grafana_url: 'http://localhost:5050' } });
