import { DEFAULT_DATABASE, databaseOf } from '../../src/core/database-of';
import * as compose from '../../src/lib/compose';
import { metadata, write } from '../../src/core/runner/record';

interface Case {
  name: string;
  environment?: unknown;
  services?: Record<string, unknown>;
  /** The database earlier releases answered for this document, recorded. */
  expected: string;
}

/**
 * The two edges `perf.mongoprof -> backup` and `scaleseed -> backup`, held to the answers
 * earlier releases gave.
 *
 * Earlier releases reached the backup module's lookup through a guarded deferred import,
 * whose failure branch answered the plain default. This build hoists the function into
 * `core/database-of.ts` — the layering rule's own remedy for something two lower modules
 * need — so what this compares is the REAL path: a MONGO_URL the workspace overrode, which
 * the plain default would answer wrongly.
 */
describe('the database a workspace actually uses', () => {
  const CASES: Case[] = [
    {
      name: 'map form, custom database',
      services: {
        rocketchat: {
          environment: { MONGO_URL: 'mongodb://mongodb:27017/customerdb?replicaSet=rs0' },
        },
      },
      expected: 'customerdb',
    },
    {
      name: 'list form, custom database',
      services: {
        rocketchat: { environment: ['MONGO_URL=mongodb://mongodb:27017/listdb', 'PORT=3000'] },
      },
      expected: 'listdb',
    },
    {
      name: 'no database in the URL',
      services: { rocketchat: { environment: { MONGO_URL: 'mongodb://mongodb:27017' } } },
      expected: 'rocketchat',
    },
    {
      name: 'no MONGO_URL at all',
      services: { rocketchat: { environment: { PORT: '3000' } } },
      expected: 'rocketchat',
    },
    {
      name: 'the first multi-instance service when rocketchat is absent',
      services: { 'rocketchat-1': { environment: { MONGO_URL: 'mongodb://x:27017/instdb' } } },
      expected: 'instdb',
    },
    {
      // An EMPTY primary service counts as absent and falls through to the instance.
      // `??` answered the default database for this document.
      name: 'an empty primary service falls through to the first instance',
      services: {
        rocketchat: {},
        'rocketchat-1': { environment: { MONGO_URL: 'mongodb://x:27017/instdb' } },
      },
      expected: 'instdb',
    },
    {
      // Everything after the FIRST scheme separator is the rest of the URL.
      // `split('://').at(-1)` took the text after the LAST one.
      name: 'a URL carrying two scheme separators',
      services: { rocketchat: { environment: { MONGO_URL: 'mongodb://a://b' } } },
      expected: '/b',
    },
    { name: 'no services key at all', services: {}, expected: 'rocketchat' },
  ];

  it('answers what earlier releases answered on every document shape', async () => {
    for (const [index, testCase] of CASES.entries()) {
      const name = `d${String(index)}`;
      const doc = { services: testCase.services ?? {}, volumes: {} };
      await write(
        name,
        compose.toYaml(doc as unknown as compose.ComposeDoc),
        metadata({ name, project: `houston-${name}` }),
      );
      expect(await databaseOf(name)).toBe(testCase.expected);
    }
    expect(await databaseOf('no-such-workspace')).toBe(DEFAULT_DATABASE);
  });

  it('is what the two former deferred-edge callers now address', async () => {
    // The consumers' own `dbOf` must answer the workspace's database, not the constant.
    const name = 'consumer';
    await write(
      name,
      compose.toYaml({
        services: { rocketchat: { environment: { MONGO_URL: 'mongodb://m:27017/realdb' } } },
        volumes: {},
      } as unknown as compose.ComposeDoc),
      metadata({ name, project: 'houston-consumer' }),
    );
    const scaleseed = require('../../src/core/scaleseed') as {
      dbOf: (n: string) => Promise<string>;
    };
    const mongoprof = require('../../src/perf/mongoprof') as {
      dbOf: (n: string) => Promise<string>;
    };
    expect(await scaleseed.dbOf(name)).toBe('realdb');
    expect(await mongoprof.dbOf(name)).toBe('realdb');
    // And the fallback is still distinguished: no record, no custom name.
    expect(await scaleseed.dbOf('no-such-workspace')).toBe(DEFAULT_DATABASE);
    expect(await mongoprof.dbOf('no-such-workspace')).toBe(DEFAULT_DATABASE);
  });
});

import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';

import {
  RC_METRICS_ENV,
  RC_METRICS_SETTING,
  SERVICES,
  VOLUMES,
  bindPorts,
  dashboard,
  files,
  grafanaUrl,
  isMonitoringNote,
  notes,
  sd,
  services,
  volumes,
} from '../../src/lib/monitoring';

/** What earlier releases built for the same inputs, recorded. */
const RECORDED = JSON.parse(
  fs.readFileSync(path.join(__dirname, '..', 'fixtures', 'lib', 'monitoring.json'), 'utf8'),
) as {
  names: Record<string, unknown>;
  volumes: unknown;
  services: unknown;
  bound_ports: unknown;
  paths: string[];
  content_sha256: [string, string][];
  notes: string[];
};

const RC_SERVICES = ['rocketchat-1', 'rocketchat-2'];
const PROJECT = 'houston-demo';

describe('the compose half', () => {
  it('names the same services and volumes earlier releases do', () => {
    const recorded = RECORDED.names;
    expect(recorded.services).toEqual([...SERVICES]);
    expect(recorded.volumes).toEqual([...VOLUMES]);
    expect(recorded.setting).toBe(RC_METRICS_SETTING);
    expect(recorded.env).toBe(RC_METRICS_ENV);
  });

  it('declares the same named volumes earlier releases declare', () => {
    expect(RECORDED.volumes).toEqual(volumes());
  });

  it('builds the same service documents, including the images', () => {
    expect(RECORDED.services).toEqual(services());
  });

  it('binds only the services that publish a port', () => {
    expect(RECORDED.bound_ports).toEqual(bindPorts(services(), '127.0.0.1'));
    // The exporters publish nothing and must be left untouched.
    expect(bindPorts(services(), '127.0.0.1')['node-exporter']).not.toHaveProperty('ports');
  });
});

describe('the config files written into a workspace', () => {
  it('is the same list of paths, in the same order', () => {
    expect(files(RC_SERVICES, PROJECT).map(([p]) => p)).toEqual(RECORDED.paths);
  });

  it('writes byte-identical CONTENTS for every one of them', () => {
    // The six embedded YAML documents are transcriptions, which is exactly the kind of
    // thing that looks right and differs by one space of indentation. They were extracted
    // from earlier releases mechanically rather than retyped, and the sha256 of each file
    // those releases wrote, recorded, is what proves it.
    const recorded = RECORDED.content_sha256;
    const mine = files(RC_SERVICES, PROJECT).map(
      ([p, c]) => [p, createHash('sha256').update(c, 'utf8').digest('hex')] as const,
    );
    expect(mine.map(([p, h]) => [p, h])).toEqual(recorded);
  });

  it('scopes the OTel collector to THIS project, so it cannot ingest another', () => {
    // The collector reads the host docker socket. Without the project filter it would
    // ship every container's logs on the box, including a real deployment's.
    const otel = files(RC_SERVICES, PROJECT).find(([p]) => p.endsWith('otel/config.yaml'));
    expect(otel?.[1]).toContain(`labels["com.docker.compose.project"] == "${PROJECT}"`);
    expect(otel?.[1]).not.toContain('__PROJECT__');
  });

  it('ships what a container wrote BEFORE the collector started, not only what follows', () => {
    // `houston monitor` on a running workspace started the collector at the END of each log
    // (the filelog default), so Rocket.Chat's boot output never reached Loki: measured, 57
    // of 65 lines missing from the "Rocket.Chat Logs" dashboard.
    const otel = files(RC_SERVICES, PROJECT).find(([p]) => p.endsWith('otel/config.yaml'));
    expect(otel?.[1]).toMatch(/\n {10}start_at: beginning\n/u);
  });

  it('generates a scrape target per Rocket.Chat service, on the metrics port', () => {
    const targets = files(RC_SERVICES, PROJECT).find(([p]) => p.endsWith('rocketchat.yml'));
    expect(targets?.[1]).toContain('    - rocketchat-1:9458');
    expect(targets?.[1]).toContain('    - rocketchat-2:9458');
  });

  it('agrees with earlier releases about a single-instance workspace too', () => {
    const recorded =
      '# Generated by houston. Prometheus scrape targets (rocketchat).\n' +
      '- targets:\n' +
      '    - rocketchat:9458\n' +
      '  labels:\n' +
      '    job: rocketchat\n' +
      '    service: rocketchat\n';
    expect(recorded).toBe(sd(['rocketchat:9458'], 'rocketchat'));
  });

  it('reads the shipped dashboards through the package-data lookup', () => {
    // A bundler rewrites this lookup, which is a Grafana with an empty folder and no
    // error anybody sees.
    expect(() => dashboard('houston-logs.json')).not.toThrow();
    expect(JSON.parse(dashboard('houston-logs.json'))).toHaveProperty('uid', 'houston-logs');
  });
});

describe('the notes printed after attach', () => {
